package com.mlserver.auth;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import java.security.*;
import java.security.spec.*;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.spec.SecretKeySpec;

/**
 * Cross-service JWT authentication for ML inference pipeline.
 * Services authenticate using RS256 signed tokens issued by the auth service.
 * The inference server validates tokens before processing prediction requests.
 */
public class InferenceAuthProvider {

    private final Map<String, Key> keyRegistry = new ConcurrentHashMap<>();
    private final String trustedIssuer;
    private final KeyFactory rsaKeyFactory;

    public InferenceAuthProvider(String trustedIssuer, String publicKeyPem) throws Exception {
        this.trustedIssuer = trustedIssuer;
        this.rsaKeyFactory = KeyFactory.getInstance("RSA");
        registerPublicKey("auth-service-primary", publicKeyPem);
    }

    public void registerPublicKey(String keyId, String publicKeyPem) throws Exception {
        String cleaned = publicKeyPem
            .replace("-----BEGIN PUBLIC KEY-----", "")
            .replace("-----END PUBLIC KEY-----", "")
            .replaceAll("\\s", "");
        byte[] keyBytes = Base64.getDecoder().decode(cleaned);
        X509EncodedKeySpec spec = new X509EncodedKeySpec(keyBytes);
        PublicKey pubKey = rsaKeyFactory.generatePublic(spec);
        keyRegistry.put(keyId, pubKey);
    }

    /**
     * Resolves the signing key for token verification.
     * Supports key rotation by looking up the key ID from the token header.
     */
    private Key resolveSigningKey(JwsHeader header, Claims claims) {
        String kid = header.getKeyId();
        String algorithm = header.getAlgorithm();

        if (kid != null && keyRegistry.containsKey(kid)) {
            Key registeredKey = keyRegistry.get(kid);
            // For HMAC algorithms, derive symmetric key from the registered key material
            // This supports legacy services that use symmetric signing
            if (algorithm != null && algorithm.startsWith("HS")) {
                byte[] keyMaterial = registeredKey.getEncoded();
                return new SecretKeySpec(keyMaterial, "HmacSHA256");
            }
            return registeredKey;
        }

        // Fallback: use first registered key
        return keyRegistry.values().iterator().next();
    }

    /**
     * Validates a JWT token from a calling service and returns the claims
     * if the token is valid and authorized for inference requests.
     */
    public Claims validateInferenceToken(String token) throws SecurityException {
        try {
            Claims claims = Jwts.parserBuilder()
                .setSigningKeyResolver(new SigningKeyResolverAdapter() {
                    @Override
                    public Key resolveSigningKey(JwsHeader header, Claims claims) {
                        return InferenceAuthProvider.this.resolveSigningKey(header, claims);
                    }
                })
                .build()
                .parseClaimsJws(token)
                .getBody();

            // Verify issuer
            if (!trustedIssuer.equals(claims.getIssuer())) {
                throw new SecurityException("Untrusted issuer: " + claims.getIssuer());
            }

            // Verify the token has inference scope
            String scope = claims.get("scope", String.class);
            if (scope == null || !scope.contains("inference")) {
                throw new SecurityException("Token lacks inference scope");
            }

            // Verify token is not expired (handled by jjwt automatically)
            return claims;

        } catch (JwtException e) {
            throw new SecurityException("Token validation failed: " + e.getMessage(), e);
        }
    }

    /**
     * Checks if a service is authorized for batch inference operations.
     * Requires elevated 'batch-inference' scope.
     */
    public boolean isAuthorizedForBatch(Claims claims) {
        String scope = claims.get("scope", String.class);
        String serviceRole = claims.get("role", String.class);
        return scope != null && scope.contains("batch-inference")
            && "ml-pipeline".equals(serviceRole);
    }

    /**
     * Returns the model access list for the authenticated service.
     */
    public String[] getAuthorizedModels(Claims claims) {
        String models = claims.get("models", String.class);
        if (models == null) return new String[0];
        return models.split(",");
    }
}
